import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';

const read = file => readFileSync(file, 'utf8');
const json = file => JSON.parse(read(file));
const programme = json('data/programa-uc3m-auxiliar-administrativa-2026.json');
const t14 = programme.temas.find(t => t.numero === 14);
const t15 = programme.temas.find(t => t.numero === 15);
assert.equal(t14.estado, 'AUDITADO');
assert.equal(t15.estado, 'EN_REVISION_USUARIO', 'No certificar T15 sin resolver divergencias 2003/LOSU 2023');
assert.equal(json(t14.matriz).estado, 'AUDITADO');
const bank = json(t14.preguntas).preguntas;
assert.equal(bank.length, 14);
assert.ok(bank.every(q => q.respuestaLiteral === q.opciones[q.correcta]), 'Clave literal errónea T14');
assert.ok(bank.every(q => q.referencia.includes(q.id === 'UC3M-T14-003' ? 'BOE-A-2003-17782' : 'BOE-A-2023-7500')), 'Fuente de respuesta ausente');
const acta = read(t14.actaAuditoria);
assert.match(acta, /RD 855\/2026/);
assert.match(acta, /22\/10\/2026/);
assert.match(acta, /25 %/);
assert.match(acta, /5 %/);
const manual15 = read(t15.manual);
assert.match(manual15, /50 estudiantes/);
assert.match(manual15, /25 %/);
assert.match(manual15, /\*\*3 años\*\* es el plazo vigente/);
assert.match(manual15, /\*\*2 años\*\* de la redacción original/);
assert.doesNotMatch(manual15, /\*\*2 años\*\* es el plazo de la transitoria LOSU modificada/);
assert.match(manual15, /EN_REVISION_USUARIO/);
assert.ok(read(t15.fuentes).includes('disposición transitoria primera'));
const m15 = json(t15.matriz);
assert.equal(m15.cobertura.length, 7);
assert.equal(m15.cobertura[0].microtestManual.enBancoJson, false);
console.log('UC3M T14 AUDITADO con 14 respuestas; T15 reservado por diferencias Estatutos originales/LOSU y corte.');
